import type { Record as DBRecord } from '../db'
import type { Workspace } from '../uxf'

export type DashboardWidget = Now.Internal.WithID<{
    /**
     * Component identifier - can be either:
     * - A human-readable component name in kebab-case (e.g., 'line', 'pie', 'single-score')
     * - A component sys_id (32-character hex string)
     *
     * Component names are case-insensitive.*/
    component:
        | 'area'
        | 'boxplot'
        | 'bubble'
        | 'calendar-report'
        | 'column'
        | 'compatibility-mode-widget'
        | 'dial'
        | 'donut'
        | 'gauge'
        | 'geomap'
        | 'heading'
        | 'heatmap'
        | 'horizontal-bar'
        | 'image'
        | 'indicator-scorecard'
        | 'line'
        | 'list'
        | 'pareto'
        | 'pie'
        | 'pivot-table'
        | 'rich-text'
        | 'scatter'
        | 'semi-donut'
        | 'single-score'
        | 'spline'
        | 'step'
        | 'vertical-bar'
        | string
    /** Component properties as a JSON object */
    componentProps: Record<string, unknown>
    /** Height of the widget */
    height: number
    /** Width of the widget */
    width: number
    position: {
        /** X position of the widget */
        x: number
        /** Y position of the widget */
        y: number
    }
}> &
    Now.Internal.Meta

export type DashboardTab = Now.Internal.WithID<{
    /** Name of the tab */
    name: string
    /** Whether the tab is active (defaults to true) */
    active?: boolean
    /** Array of widgets in this tab */
    widgets: DashboardWidget[]
}> &
    Now.Internal.Meta

export type DashboardTopLayout = {
    /** Array of widgets in this tab */
    widgets: DashboardWidget[]
} & Now.Internal.Meta

export type DashboardVisibility = Now.Internal.WithID<{
    /** UX experience reference (sys_id or reference to sys_ux_page_registry) */
    experience: string | Workspace
}> &
    Now.Internal.Meta

type DashboardPermissionSubject =
    | { user: string | DBRecord<'sys_user'>; group?: never; role?: never }
    | { group: string | DBRecord<'sys_user_group'>; user?: never; role?: never }
    | { role: string | DBRecord<'sys_user_role'>; user?: never; group?: never }

type DashboardPermissionFlags = {
    /** Whether the user can read the dashboard (defaults to true) */
    canRead?: boolean
    /** Whether the user can write/edit the dashboard (defaults to false) */
    canWrite?: boolean
    /** Whether the user can share the dashboard (defaults to false) */
    canShare?: boolean
    /** Whether the user is the owner of the dashboard (defaults to false) */
    owner?: boolean
}

export type DashboardPermission = Now.Internal.WithID<
    (DashboardPermissionSubject & DashboardPermissionFlags) & Now.Internal.Meta
>

export type Dashboard = Now.Internal.WithID<{
    /** Name of the dashboard */
    name: string
    /** Whether the dashboard is active (defaults to true) */
    active?: boolean
    /** Array of top-level widgets (displayed outside of tabs) */
    topLayout?: DashboardTopLayout
    /** Array of tabs in the dashboard */
    tabs?: DashboardTab[]
    /** Array of visibility rules for the dashboard */
    visibilities?: DashboardVisibility[]
    /** Array of user permissions for the dashboard */
    permissions?: DashboardPermission[]
}> &
    Now.Internal.Meta

/**
 * Creates a Dashboard (`par_dashboard`).
 *
 * @see https://docs.servicenow.com/csh?topicname=dashboard-api-now-ts.html&version=latest
 *
 * @param config - an object containing the following properties:
 *   * **$id** - unique id for the record, typically using `Now.ID["value"]`
 *   * **name** - The name of the dashboard
 *   * **tabs** - Array of dashboard tabs (each with $id, name, and widgets array)
 *   * **visibilities** - Array of visibility rules (each with $id, type, and value)
 *   * **permissions** - Array of user permissions (each with $id, user, can_read, can_write, can_share, owner)
 *
 * @example
 * ```typescript
 * Dashboard({
 *   $id: Now.ID['my-dashboard'],
 *   name: 'My Dashboard',
 *   tabs: [
 *     {
 *       $id: Now.ID['tab-1'],
 *       name: 'Overview',
 *       widgets: [
 *         {
 *           $id: Now.ID['widget-1'],
 *           component: 'component-id',
 *           componentProps: { key: 'value' },
 *           height: 12,
 *           width: 12,
 *           position: {
 *              x: 0,
 *              y: 0,
 *          }
 *         },
 *       ],
 *     },
 *   ],
 *   permissions: [
 *     {
 *       $id: Now.ID['perm-1'],
 *       user: 'user-sys-id',
 *       canRead: true,
 *       canWrite: true,
 *       canShare: true,
 *       owner: true,
 *     },
 *   ],
 *   visibilities: [],
 * })
 * ```
 */
export function Dashboard(config: Dashboard): Dashboard {
    return config
}
